test-case.test:
declare namespace p = 'http://p';
deep-equal(map-to-element({ 'p:x': 'v' }, { 'name-format': 'lexical' }),
   parse-xml('<p:x xmlns:p="http://p">v</p:x>')/*)

let $e := parse-xml('<a x="1">t</a>')/*
let $o := { 'name-format': 'eqname' }
return deep-equal($e, map-to-element(element-to-map($e, $o), $o))

let $e := parse-xml('<a x="1">t</a>')/*
let $o := { 'attribute-marker': ':' }
return deep-equal($e, map-to-element(element-to-map($e, $o), $o))

let $e := parse-xml('<a x="1">t</a>')/*
let $o := { 'content-key': 'value' }
return deep-equal($e, map-to-element(element-to-map($e, $o), $o))

let $e := parse-xml('<a><b><c>1</c><c>2</c></b></a>')/*
let $o := { 'plan': element-to-map-plan($e) }
return deep-equal($e, map-to-element(element-to-map($e, $o), $o))

let $e := parse-xml('<a x="1"><b>1</b><b>2</b></a>')/*
let $o := { 'plan': element-to-map-plan($e) }
return deep-equal($e, map-to-element(element-to-map($e, $o), $o))

let $e := parse-xml('<a><b x="1">t</b></a>')/*
let $o := { 'plan': { 'a': { 'layout': 'xml' } } }
return deep-equal($e, map-to-element(element-to-map($e, $o), $o))
